---- LOOK AND FEEL ----
-----------------------

-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
    general = {
        gaps_in  = 5,
        gaps_out = 20,

        border_size = 2,

        col = {
            active_border   = { colors = {"rgba(33ccffee)", "rgba(00ff99ee)"}, angle = 45 },
            inactive_border = "rgba(595959aa)",
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        rounding       = 10,
        rounding_power = 2,

        -- Change transparency of focused and unfocused windows
        active_opacity   = 1.0,
        inactive_opacity = 1.0,

        shadow = {
            enabled      = true,
            range        = 4,
            render_power = 3,
            color        = 0xee1a1a1a,
        },

        blur = {
		   	enabled   = true,
            size      = 3,
            passes    = 1,
            vibrancy  = 0.1696,
        },
    },

    animations = {
        enabled = true,
    },
})

hl.curve("workFast", { type = "bezier", points = { {0.05, 0.9}, {0.1, 1.0} } })

hl.animation({ leaf = "global",        enabled = true,  speed = 4.0, bezier = "workFast" })
hl.animation({ leaf = "border",        enabled = false }) 

hl.animation({ leaf = "windows",       enabled = true,  speed = 3.5, bezier = "workFast" })
hl.animation({ leaf = "windowsIn",      enabled = true,  speed = 3.5, bezier = "workFast" })
hl.animation({ leaf = "windowsOut",    enabled = true,  speed = 3.0, bezier = "workFast" }) 
hl.animation({ leaf = "windowsMove",   enabled = true,  speed = 4.0, bezier = "workFast" })

hl.animation({ leaf = "fade",          enabled = true,  speed = 3.0, bezier = "workFast" })
hl.animation({ leaf = "fadeIn",        enabled = true,  speed = 3.0, bezier = "workFast" })
hl.animation({ leaf = "fadeOut",       enabled = true,  speed = 2.5, bezier = "workFast" })

hl.animation({ leaf = "layers",        enabled = true,  speed = 3.5, bezier = "workFast" })
hl.animation({ leaf = "layersIn",      enabled = true,  speed = 3.5, bezier = "workFast" })
hl.animation({ leaf = "layersOut",     enabled = true,  speed = 3.0, bezier = "workFast" })
hl.animation({ leaf = "fadeLayersIn",  enabled = true,  speed = 3.0, bezier = "workFast" })
hl.animation({ leaf = "fadeLayersOut", enabled = true,  speed = 2.5, bezier = "workFast" })

hl.animation({ leaf = "workspaces",    enabled = true,  speed = 4.0, bezier = "workFast" })
hl.animation({ leaf = "workspacesIn",  enabled = true,  speed = 4.0, bezier = "workFast" })
hl.animation({ leaf = "workspacesOut", enabled = true,  speed = 4.0, bezier = "workFast" })
hl.animation({ leaf = "zoomFactor",    enabled = true,  speed = 4.0, bezier = "workFast" })

