---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + Q", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + SHIFT + Escape", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + D", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + Y", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + V", hl.dsp.layout("togglesplit"))    
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen())
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd(terminal .. " yazi"))

hl.bind(mainMod .. " + G", function()
    hl.dispatch(hl.dsp.window.float({ action = "toggle" }))
    hl.dispatch(hl.dsp.window.resize({ x = 900, y = 600 }))
	hl.dispatch(hl.dsp.window.center())
end)

hl.bind("ALT + Tab", hl.dsp.window.cycle_next())

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + H",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + L", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + K",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + J",  hl.dsp.focus({ direction = "down" }))

-- Move windows with mainMod + SHIFT + H/J/K/L
hl.bind(mainMod .. " + SHIFT + H", hl.dsp.window.move({ direction = "left" }))
hl.bind(mainMod .. " + SHIFT + J", hl.dsp.window.move({ direction = "down" }))
hl.bind(mainMod .. " + SHIFT + K", hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + L", hl.dsp.window.move({ direction = "right" }))

-- Resize windows with mainMod + U/I/O/P
local resizeStep = 30

hl.bind(mainMod .. " + U", hl.dsp.window.resize({ x = -resizeStep, y = 0,            relative = true }), { repeating = true })
hl.bind(mainMod .. " + I", hl.dsp.window.resize({ x = 0,           y = -resizeStep,  relative = true }), { repeating = true })
hl.bind(mainMod .. " + O", hl.dsp.window.resize({ x = 0,           y = resizeStep,   relative = true }), { repeating = true })
hl.bind(mainMod .. " + P", hl.dsp.window.resize({ x = resizeStep,  y = 0,            relative = true }), { repeating = true })

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl set +750"),                  	   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("brightnessctl set 750-"),                  	   { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })

-- Print Screen
hl.bind("Print", hl.dsp.exec_cmd('grim -g "$(slurp)" - | swappy -f -'))
hl.bind(mainMod .. " + Print", hl.dsp.exec_cmd('grim - | swappy -f -'))

-- PowerMenu
hl.bind(mainMod .. " + Escape", hl.dsp.exec_cmd("~/.config/rofi/scripts/powermenu.sh"))
hl.bind(mainMod .. " + SHIFT + R", hl.dsp.exec_cmd("systemctl reboot"))
hl.bind(mainMod .. " + SHIFT + X", hl.dsp.exec_cmd("systemctl poweroff"))

-- Change Wallpaper
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd("~/.config/hypr/scripts/wallpapers.sh"))
hl.bind(mainMod .. " + SHIFT + B", hl.dsp.exec_cmd("~/.config/rofi/scripts/wallmenu.sh"))

-- Change Window
hl.bind(mainMod .. " + A", hl.dsp.exec_cmd("~/.config/rofi/scripts/rofi-move.sh"))

-- Mouse Movement
local mouseStep = 10

hl.bind(mainMod .. " + CTRL + H", hl.dsp.exec_cmd("ydotool mousemove -x -" .. mouseStep .. " -y 0"), { repeating = true })
hl.bind(mainMod .. " + CTRL + J", hl.dsp.exec_cmd("ydotool mousemove -x 0 -y " .. mouseStep), { repeating = true })
hl.bind(mainMod .. " + CTRL + K", hl.dsp.exec_cmd("ydotool mousemove -x 0 -y -" .. mouseStep), { repeating = true })
hl.bind(mainMod .. " + CTRL + L", hl.dsp.exec_cmd("ydotool mousemove -x " .. mouseStep .. " -y 0"), { repeating = true })

hl.bind(mainMod .. " + CTRL + F", hl.dsp.exec_cmd("ydotool click 0xC0")) 
hl.bind(mainMod .. " + CTRL + D", hl.dsp.exec_cmd("ydotool click 0xC1"))

-- Cool Retro Terminal
hl.bind(mainMod .. " + SHIFT + T", hl.dsp.exec_cmd("cool-retro-term"))

-- Rofi Filebrowser
hl.bind(mainMod .. " + SHIFT + E", hl.dsp.exec_cmd("rofi -show filebrowser -filebrowser-directory ~")) 

-- Rofi Wifi and Bluetooth
hl.bind(mainMod .. " + W", hl.dsp.exec_cmd("~/.config/rofi/scripts/rofi-wifi.sh")) 
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.exec_cmd("~/.config/rofi/scripts/rofi-bluetooth.sh"))

-- Btop Bind
hl.bind(mainMod .. " + N", hl.dsp.exec_cmd(terminal .. " -e btop"))

-- Music Bind
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("audacious"))

-- Waybar Bind
hl.bind(mainMod .. " + SPACE", hl.dsp.exec_cmd("~/.config/waybar/toggle-style.sh"))

-- Rofi Theme Selector
hl.bind(mainMod .. " + SHIFT + D", hl.dsp.exec_cmd("~/.config/rofi/scripts/theme-selector.sh"))

-- Rofimoji Bind
hl.bind(mainMod .. " + period", hl.dsp.exec_cmd("rofimoji --selector rofi --clipboarder wl-copy --typer wtype"))

